const incoming = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const order = incoming.order && typeof incoming.order === 'object' ? incoming.order : {};
const expectedSecret = String($env.N8N_PAID_ORDER_WEBHOOK_SECRET || '');
const secretValid = Boolean(expectedSecret) && incoming.sharedSecret === expectedSecret;
const cart = Array.isArray(order.raw_payload?.cart) ? order.raw_payload.cart : [];
const itemsText = cart.length > 0
  ? cart.map((item) => {
      const quantity = Number(item.qty || item.quantity || 0);
      const unitPrice = Number(item.price || 0);
      const volume = String(item.volumeLabel || item.weight || '').trim();
      const grind = String(item.grindLabel || '').trim();
      const details = [grind, volume].filter(Boolean).join(', ');
      return `- ${item.title || 'Товар'} x${quantity}${details ? ` (${details})` : ''} = ${quantity * unitPrice} грн`;
    }).join('\n')
  : String(order.items_summary || '-').split(/,\s*/u).filter(Boolean).map((item) => `- ${item}`).join('\n');

const text = [
  'Нове замовлення з сайту Odesa Coffee Roasters',
  '',
  `Клієнт: ${order.customer_name || '-'}`,
  `Email: ${order.customer_email || '-'}`,
  `Телефон: ${order.customer_phone || '-'}`,
  `Місто: ${order.city || '-'}`,
  `Доставка: ${order.delivery_method_label || '-'}`,
  `Деталі доставки: ${order.delivery_details || '-'}`,
  `Оплата: ${order.payment_method_label || 'Mono'} (оплачено)`,
  `Коментар до замовлення: ${order.comment || '-'}`,
  `Сума: ${Number(order.total_amount || 0)} грн`,
  '',
  'Товари:',
  itemsText,
  '',
  `Дата: ${order.placed_at || new Date().toISOString()}`,
  `Джерело: ${order.source || 'website'}`,
  `Номер замовлення: #${order.order_number || '-'}`
].join('\n');

return [{ json: { secretValid, text } }];
